import{_ as t,o,c as a,aj as n,j as r}from"./chunks/framework.C6uXqnaX.js";const d=JSON.parse('{"title":"Runtime performance optimization","description":"","frontmatter":{"untranslated":true},"headers":[],"relativePath":"best-practices/runtime-performance.md","filePath":"best-practices/runtime-performance.md"}'),i={name:"best-practices/runtime-performance.md"};function s(c,e,p,m,l,h){return o(),a("div",null,e[0]||(e[0]=[n('<h1 id="runtime-performance-optimization" tabindex="-1">Runtime performance optimization <a class="header-anchor" href="#runtime-performance-optimization" aria-label="Permalink to &quot;Runtime performance optimization&quot;">​</a></h1><p>Fast rendering is critical for Angular and we&#39;ve built the framework with a lot of optimizations in mind to help you develop performant apps. To better understand the performance of your app we offer <a href="/tools/devtools">Angular DevTools</a> and a <a href="https://www.youtube.com/watch?v=FjyX_hkscII" target="_blank" rel="noreferrer">video guide</a> on how to use Chrome DevTools for profiling. In this section we cover the most common performance optimization techniques.</p><p><strong>Change detection</strong> is the process through which Angular checks to see whether your application state has changed, and if any DOM needs to be updated. At a high level, Angular walks your components from top to bottom, looking for changes. Angular runs its change detection mechanism periodically so that changes to the data model are reflected in an application’s view. Change detection can be triggered either manually or through an asynchronous event (for example, a user interaction or an XMLHttpRequest completion).</p><p>Change detection is highly optimized and performant, but it can still cause slowdowns if the application runs it too frequently.</p><p>In this guide, you’ll learn how to control and optimize the change detection mechanism by skipping parts of your application and running change detection only when necessary.</p><p>Watch this video if you prefer to learn more about performance optimizations in a media format:</p>',6),r("iframe",{src:"https://www.youtube.com/embed/f8sA-i6gkGQ",title:"Video",style:{width:"100%","aspect-ratio":"16/9",border:"0"},allowfullscreen:""},null,-1)]))}const f=t(i,[["render",s]]);export{d as __pageData,f as default};
